using System;using System.Collections.Generic;using System.Linq;using UnityEngine;
[ExecuteAlways,DefaultExecutionOrder(-200)]public sealed class ScaleBake378:MonoBehaviour{
 public HeadLocal367 host;public CurrentSurface330 original;Mesh[]meshes;bool ready,oldEnabled;bool[]priorSourceEnabled;Action previous,hook;
 List<Vector3>[]vertsBuf,normsBuf;List<Vector4>[]tangentsBuf;int lastEvaluatedFrame=-1;
 void OnEnable()=>Initialise();
 public void Initialise(){if(ready||!host||!original||original.source==null)return;oldEnabled=original.enabled;original.enabled=false;priorSourceEnabled=original.source.Select(s=>s.enabled).ToArray();meshes=original.source.Select((s,i)=>new Mesh{name="378 scale-compensated current surface "+i,hideFlags=HideFlags.DontSave}).ToArray();vertsBuf=new List<Vector3>[meshes.Length];normsBuf=new List<Vector3>[meshes.Length];tangentsBuf=new List<Vector4>[meshes.Length];for(int i=0;i<meshes.Length;i++){vertsBuf[i]=new List<Vector3>();normsBuf[i]=new List<Vector3>();tangentsBuf[i]=new List<Vector4>();}foreach(var s in original.source)s.enabled=false;previous=host.afterPose;hook=AfterPose;host.afterPose=hook;ready=true;Evaluate(true);}
 void AfterPose(){previous?.Invoke();Evaluate(false);}
 public void Evaluate()=>Evaluate(false);
 public void Evaluate(bool force){if(!ready)return;if(!force&&Application.isPlaying&&lastEvaluatedFrame==Time.frameCount)return;lastEvaluatedFrame=Time.frameCount;for(int i=0;i<meshes.Length;i++){var src=original.source[i];var m=meshes[i];src.BakeMesh(m,true);var matrix=original.outputs[i].transform.worldToLocalMatrix*src.localToWorldMatrix;var normal=matrix.inverse.transpose;var vb=vertsBuf[i];var nb=normsBuf[i];var tb=tangentsBuf[i];m.GetVertices(vb);for(int v=0;v<vb.Count;v++)vb[v]=matrix.MultiplyPoint3x4(vb[v]);m.SetVertices(vb);m.GetNormals(nb);for(int v=0;v<nb.Count;v++)nb[v]=normal.MultiplyVector(nb[v]).normalized;m.SetNormals(nb);m.GetTangents(tb);for(int v=0;v<tb.Count;v++){var t=tb[v];var p=matrix.MultiplyVector(new Vector3(t.x,t.y,t.z));tb[v]=new Vector4(p.x,p.y,p.z,t.w);}m.SetTangents(tb);m.RecalculateBounds();original.outputs[i].sharedMesh=m;}}
 void OnDisable(){if(!ready)return;if(host&&host.afterPose==hook)host.afterPose=previous;for(int i=0;i<meshes.Length;i++){if(original&&original.outputs[i]&&original.outputs[i].sharedMesh==meshes[i])original.outputs[i].sharedMesh=null;if(meshes[i])DestroyImmediate(meshes[i]);}if(original){for(int i=0;i<original.source.Length;i++)if(original.source[i])original.source[i].enabled=priorSourceEnabled[i];original.enabled=oldEnabled;}lastEvaluatedFrame=-1;ready=false;}
}
